-- Chriz BG Script Engine runtime. Generated by tools/build_runtime.py from the authored
-- modules in this repository; edit those, then rebuild.
-- Builds on Sword Coast Stratagems (DavidW) and Spell Revisions (Demivrgvs, Gibberlings Three).
local factories,loaded={},{}
local function require(name)
  if loaded[name] then return loaded[name] end
  local value=assert(factories[name],'unbundled module')(require)
  loaded[name]=value;return value
end
factories["kernel.manifest"]=function(require)
-- Exact, scalar-only development contract. No resource discovery or native calls.
local M = {}

function M.copy(value)
    local active,nodes={},0
    local function visit(v,depth)
        nodes=nodes+1
        assert(nodes<=16384 and depth<=24,'value-limit')
        local t=type(v)
        if t=='string' then assert(#v<=256 and not v:find('\0',1,true));return v end
        if t=='boolean' or t=='nil' then return v end
        if t=='number' then assert(v==v and v>-math.huge and v<math.huge);return v end
        assert(t=='table' and getmetatable(v)==nil and not active[v],'non-scalar-value')
        active[v]=true
        local result={}
        for k,item in next,v do
            assert(type(k)=='string' or (type(k)=='number' and k%1==0),'invalid-key')
            result[visit(k,depth+1)]=visit(item,depth+1)
        end
        active[v]=nil;return result
    end
    return visit(value,0)
end

function M.equal(a,b)
    if type(a)~='table' or type(b)~='table' then return a==b end
    for k,v in pairs(a) do if not M.equal(v,b[k]) then return false end end
    for k in pairs(b) do if a[k]==nil then return false end end
    return true
end

local function text(v) return type(v)=='string' and #v>0 end
local function record(t,fields)
    if type(t)~='table' then return false end
    local allowed={};for _,k in ipairs(fields) do allowed[k]=true;if t[k]==nil then return false end end
    for k in pairs(t) do if not allowed[k] then return false end end
    return true
end
local function array(t,check,nonempty)
    if type(t)~='table' then return false end
    local count,seen=0,{}
    for k,v in pairs(t) do
        if type(k)~='number' or k<1 or k%1~=0 or not check(v) or seen[v] then return false end
        seen[v]=true;count=count+1
    end
    if nonempty and count==0 then return false end
    for i=1,count do if t[i]==nil then return false end end
    return true
end
local function resref(v) return text(v) and #v<=8 and not v:find('[^A-Z0-9_#-]') end
local extensions={CRE=true,BCS=true,DLG=true,ARE=true,SPL=true,ITM=true,PRO=true,IDS=true,['2DA']=true}
local function resource(v)
    if not text(v) then return false end
    local stem,ext=v:match('^([^%.]+)%.([^%.]+)$')
    return resref(stem) and extensions[ext]==true
end
local function digest(v) return type(v)=='string' and #v==64 and not v:find('[^a-f0-9]') end
local slotNames={override=true,class=true,race=true,general=true,default=true,area=true}

function M.validate(input)
    local ok,m=pcall(M.copy,input)
    if not ok or type(m)~='table' then return nil,'manifest-shape' end
    if m.schemaVersion~=1 then return nil,'manifest-schema' end
    if not text(m.id) or #m.id>64 or not m.id:match('^B%-/[a-z]+/[a-z0-9][a-z0-9%-]*$')
        or m.id:find('%-%-') or m.id:sub(-1)=='-' then return nil,'manifest-id' end
    local domain=m.id:match('^B%-/([^/]+)/')
    if not ((domain=='combat' and m.domain=='CombatIntent') or
        (domain=='worldflow' and m.domain=='WorldFlow')) then return nil,'manifest-domain' end
    if not text(m.version) then return nil,'manifest-version' end
    if not ({C0=true,C1=true,C2=true,C3=true,C4=true})[m.tier] then return nil,'manifest-tier' end
    if m.hashAlgorithm~='sha256' or m.hashVersion~=1 then return nil,'manifest-hash' end
    if not record(m.fallback,{'kind','resources'}) or m.fallback.kind~='legacy' or
        not array(m.fallback.resources,resource,true) then return nil,'manifest-fallback' end
    if not record(m.provenance,{'source','distribution'}) or not text(m.provenance.source) or
        not text(m.provenance.distribution) then return nil,'manifest-provenance' end
    if not array(m.evidence,text,true) then return nil,'manifest-evidence' end
    if not record(m,{'schemaVersion','id','version','domain','tier','profile','epoch',
        'hashAlgorithm','hashVersion','requiredCapabilities','roots','controlClosure','resources',
        'publicState','fallback','provenance','evidence'}) or not text(m.profile) or not text(m.epoch)
        or not array(m.requiredCapabilities,text,true) or not array(m.roots,resource,true)
        or not array(m.controlClosure,resource,false) or type(m.resources)~='table'
        or type(m.publicState)~='table' then return nil,'manifest-shape' end
    for id,r in pairs(m.resources) do
        if not resource(id) or not record(r,{'sha256','dependencies','slots','opaque'}) or
            not digest(r.sha256) or not array(r.dependencies,resource,false) or
            type(r.slots)~='table' or r.opaque~=false then return nil,'manifest-shape' end
        for slot,stem in pairs(r.slots) do
            if not slotNames[slot] or (stem~='' and not resref(stem)) then return nil,'manifest-shape' end
            if stem~='' and not m.resources[stem..'.BCS'] then return nil,'manifest-closure' end
        end
    end
    local reached={}
    local function walk(id)
        if reached[id] then return true end
        local r=m.resources[id];if not r then return false end
        reached[id]=true
        for _,child in ipairs(r.dependencies) do if not walk(child) then return false end end
        for _,stem in pairs(r.slots) do if stem~='' and not walk(stem..'.BCS') then return false end end
        return true
    end
    for _,ids in ipairs({m.roots,m.controlClosure,m.fallback.resources}) do
        for _,id in ipairs(ids) do if not walk(id) then return nil,'manifest-closure' end end
    end
    for id in pairs(m.resources) do if not reached[id] then return nil,'manifest-closure' end end
    for variable,refs in pairs(m.publicState) do
        if not text(variable) or not variable:match('^[A-Z0-9_]+:[A-Z0-9_%-]+$') or
            not record(refs,{'readers','writers'}) or not array(refs.readers,resource,false) or
            not array(refs.writers,resource,false) then return nil,'manifest-public-state' end
        for _,ids in ipairs({refs.readers,refs.writers}) do
            for _,id in ipairs(ids) do if not reached[id] then return nil,'manifest-closure' end end
        end
    end
    return m
end

return M
end
factories["kernel.trace"]=function(require)
local values=require('kernel.manifest')
local M={}
function M.new(capacity)
    assert(type(capacity)=='number' and capacity%1==0 and capacity>=1 and capacity<=4096)
    local rows,nextSlot,size={},1,0
    local fields={'kind','actorKey','adapterId','profile','snapshotVersion','owner','family','reason','tick'}
    local api={}
    function api:record(event)
        local row={}
        for _,field in ipairs(fields) do
            local value=rawget(event,field)
            if value~=nil then
                assert(type(value)=='string' or type(value)=='number','trace scalar required')
                row[field]=values.copy(value)
            end
        end
        rows[nextSlot]=row;nextSlot=nextSlot%capacity+1;size=math.min(size+1,capacity)
    end
    function api:snapshot()
        local result={};local first=(nextSlot-size-1)%capacity+1
        for i=0,size-1 do result[#result+1]=values.copy(rows[(first+i-1)%capacity+1]) end
        return result
    end
    return api
end
return M
end
factories["kernel.hook"]=function(require)
-- BCS handoff gate. A hook block in a creature's script calls claim() each time it is
-- reached: true means the engine performs this round's action, false lets the creature's own
-- blocks run on. Guarded copies of SCS blocks above the hook ask the same question in the same
-- script pass, so the gate answers once per creature and tick and repeats that answer.
-- A creature can carry hooked scripts in several slots (an SCS monster script above SCS's
-- general AI, for example). Slots run from override down to default, and a lower script is
-- reached only after the higher ones let the pass through, so the first hooked script that
-- asks in a pass decides for the creature; the others decline in that pass. The engine also
-- declines when a script that carries no hook sits below the deciding one: an engine round
-- would keep that script from ever running.
-- Nothing here raises to the caller and nothing in it survives a load.
local values=require('kernel.manifest')
local trace=require('kernel.trace')
local M={}
M.families={'mage','priest','fighter','monster'}
local known={};for _,family in ipairs(M.families) do known[family]=true end
local function scalarId(id) return type(id)=='number' and id>=0 and id<4294967296 and id%1==0 end
local function count(value,limit) return type(value)=='number' and value>=0 and value<=limit and value%1==0 end
function M.new(config)
    assert(type(config)=='table' and type(config.now)=='function','clock required')
    local backoff,maxAge=config.backoffTicks or 150,config.maxDecisionAgeTicks or 30
    assert(count(backoff,1e6) and count(maxAge,1e6))
    local enabled=config.enabled~=false
    local families={}
    for family in pairs(known) do
        families[family]=not(type(config.families)=='table' and config.families[family]==false)
    end
    local decide,perform,observe,held=config.decide,config.perform,config.observe,config.held
    assert(observe==nil or type(observe)=='function')
    assert(held==nil or type(held)=='function')
    -- hooked: script resref (lower case) -> family, from the install. below(id, script): the
    -- creature's non-empty script resrefs in the slots after script, or nil when script is not
    -- in its stack. stack(id) (optional): all its non-empty script resrefs, from the top slot down.
    local hooked,below,stack
    local function setHooked(t)
        assert(t==nil or type(t)=='table')
        if t==nil then hooked=nil;return end
        hooked={}
        for name,family in pairs(t) do
            if type(name)=='string' and #name>0 then hooked[name:lower()]=family end
        end
    end
    setHooked(config.hooked)
    below,stack=config.below,config.stack
    assert(below==nil or type(below)=='function')
    assert(stack==nil or type(stack)=='function')
    local pending,blocked,answers={},{},{}
    local counts={reached=0,repeats=0,claimed=0,acted=0,held=0,renewed=0,skipped=0,stale=0,errors=0,observeErrors=0,
        heldErrors=0}
    local declines={}
    local log=trace.new(config.traceCapacity or 64)
    local api={}
    local function bump(t,key) t[key]=math.min((t[key] or 0)+1,4294967295) end
    local function decline(reason) bump(declines,reason);return false end
    local function now()
        local ok,tick=pcall(config.now)
        if ok and count(tick,4294967295) then return tick end
    end
    local function failed(id,family,reason,tick)
        bump(counts,'errors')
        if tick then blocked[id]=tick+backoff end
        log:record({kind='error',actorKey=tostring(id),family=family,reason=reason,tick=tick})
    end
    -- Whether a decider's answer, copied (copied, result), is no plain decision, hold or idle hold.
    local function bad(copied,result)
        return not copied or type(result)~='table' or (result.hold~=nil and result.hold~=true) or
            (result.idle~=nil and (result.idle~=true or result.hold~=true))
    end
    local function evaluate(id,actor,family,tick,script)
        if not enabled then return decline('disabled') end
        if not known[family] then return decline('unknown-family') end
        if not families[family] then return decline('family-off') end
        if not hooked then return decline('no-registry') end
        if not below then return decline('no-stack') end
        local found,rest=pcall(below,id,script)
        if not found then failed(id,family,'stack-error',tick);return decline('error') end
        if type(rest)~='table' then return decline('no-stack') end
        for _,name in ipairs(rest) do
            if type(name)~='string' or not hooked[name:lower()] then return decline('script-below') end
        end
        -- A load restarts the tick count, so a backoff from before it no longer applies.
        if blocked[id] and tick<blocked[id] and blocked[id]-tick<=backoff then return decline('backoff') end
        blocked[id]=nil
