    [203]={2,7,8,9,10,16,17},    -- FIGHTER_ALL
    [204]={3,8,14,15,17,18},     -- CLERIC_ALL
    [205]={4,9,10,13,15},        -- THIEF_ALL
    [206]={5},                   -- BARD_ALL
