-- The chance the caster finishes a cast of the given seconds: each hit or aimed spell that gets
-- through what protects it now can break the cast; absorbed hits do not.
function M.through(input,t,cast)
    if not t or cast<=0 then return 1 end
    local stop=quiet(input)
    if stop and cast<=stop then return 1 end
    local b=M.blocks(M.held(input.frame.self),t,1)
    local part=cast/M.ROUND
    local hits=math.max(0,t.weapon.hits*(1-b.rate)*part-b.pool)
    return math.exp(-hits-t.spell.casters*threat.personal*(1-b.personal)*part)
end

-- What a defence weakens of the enemies its area reaches as cast at aim (F2b: Prayer, Recitation
-- and Chant curse the enemies around the priest while they bless its side): each enemy's debuff
-- (combat-intent/harm.lua) against the armour class ac of the caster's side, on the attack's
-- scale; none on an enemy its spell protections keep the spell off or that carries the spell's
-- effects already.
local function weakens(input,row,spell,aim,ac)
    local area=spell.area
    if not aim.point or type(area)~='table' or not number(area.radius) then return 0 end
    local worth=0
    for _,e in ipairs(type(input.frame.enemies)=='table' and input.frame.enemies or {}) do
        if type(e)=='table' and targeting.alive(e) and targeting.distance(aim.point,e)<=area.radius and
            not targeting.protected(e,spell) and not harm.carries(e,spell,row.resref) then
            local roles=spells.view(spell,targeting.holds(e))
            local d=type(roles)=='table' and roles.debuff
            if type(d)=='table' and type(d.who)=='table' and d.who.area and
                (type(d.filters)~='table' or d.filters.enemies or d.filters.all) then
                worth=worth+harm.debuff(d,e,ac)
            end
        end
    end
    return worth
end

-- Every defence option the caster has: {resref, kind='defence', mode, worth, cost, score, hits
-- (the friends it reaches), slack=0, and self, point or target as the cast is aimed; use=true for
-- an item it drinks}. rejected (optional) counts why ready defensive spells and carried items gave
-- none. A friend's guard false means it could not be read. A defence that follows the last one
-- within mind.redefend seconds waits, as SCS's does, unless the caster is in acute danger. An item
-- (the protection and buff potions SCS's fighters drink) works on the caster itself while it has
-- uses left, costs as a first-level spell and is not interrupted (as care.lua's potions). What a
-- spell's area weakens of enemies (weakens) adds to what it gives its side, which caution weighs.
-- A defence that leaves the caster invisible as a backstab needs (plain invisibility, F2d) adds what
-- the backstab after it gains (input.hideOpening, combat-intent/choice.lua), less the part of a
-- round its casting takes (weapons.paced); such an option carries hides and that opening. A buff
-- counts over the rest of the fight as long as it lasts (rest, the seconds it reckoned with), a
-- protection over the horizon, each from the end of the caster's own Time Stop or of the calm on
-- (see the top); input.tables holds the game's strength tables (might). boosts: what
-- the option gives adds to attacks (a buff potion, which a creature drinks before its attack:
-- combat-intent/choice.lua).
function M.options(input,rejected)
    local out={}
    local function reject(why) if rejected then rejected[why]=(rejected[why] or 0)+1 end end
    local mind=input.mind
    local frame=input.frame
    if type(frame)~='table' or type(frame.self)~='table' or type(mind)~='table' then return out end
    local pictures=threat.picture(frame)
    local pause=number(mind.redefend) and mind.redefend or 0
    local waiting=number(input.lastDefence) and number(input.tick) and input.tick-input.lastDefence<pause*15
        and not M.acute(input,pictures)
    local horizon=number(mind.horizon) and mind.horizon or 18
    local rest=threat.rest(type(input.fight)=='table' and input.fight or frame,number(mind.fightCap) and mind.fightCap or 60)
    local tables=type(input.tables)=='table' and input.tables or nil
    local killBonus=number(mind.killBonus) and mind.killBonus or 0
    local stop=quiet(input) or 0
    -- Foes out of play are not where an area could weaken them.
    local away=number(input.calm)
    local held={}
    local function heldOf(f) held[f.id]=held[f.id] or M.held(f);return held[f.id] end
    local caster=frame.self
    local ct=pictures[caster.id]
    -- The weapon the caster swings when its profile fights with it.
    local wielded=mind.ownWeapon==true and threat.wielded(caster) or nil
    local caution=number(mind.caution) and mind.caution or 1
    local ac=threat.armour(threat.friends(frame))
    -- The option of one ready spell (row) or carried item (row.item), or false and why it gives
    -- none: no defence at all is false and nil.
    local function consider(row,spell)
        local gives,why=M.defence(spell)
        if not gives then
            if why~='no-defence' and why~='attack' and why~='unclassified' then return false,why end
            return false
        end
        if waiting then return false,'redefend' end
        local shield=M.shield(gives)
        local length=math.max(seconds(gives.protection),seconds(gives.buff))
        local rounds=math.max(0,math.min(horizon,length-stop))/M.ROUND
        local fights=math.max(0,math.min(rest,seconds(gives.buff)-stop))/M.ROUND
        local cast=(number(spell.speed) and spell.speed or 0)*M.speedSeconds
        local hide=input.hideOpening
        local opening=type(hide)=='table' and number(hide.worth) and hide.worth>0 and shield.invisible and
            not shield.improved and hide.worth*weapons.paced(row.item and 0 or cast) or 0
        local best,unknown
        local list=row.item and {{self=true,friend=caster,point=spell.area and {x=caster.x,y=caster.y} or nil}}
            or aims(input,row,spell)
        for _,aim in ipairs(list) do
            local worth,hits,open,boost=0,{},0,0
            for _,f in ipairs(receivers(input,row,spell,aim)) do
                if f==caster then open=opening end
                -- What protects a friend whose effects could not be read is unknown: it gets
                -- nothing rather than a second copy.
                if f.guard==false then unknown=true
                elseif not guarded(f,row.resref) then
                    local t=pictures[f.id]
                    local gain,more=0,0
                    if t and rounds>0 then
                        local now=heldOf(f)
                        gain=M.loss(now,f,t,rounds,killBonus)-M.loss(M.union(now,shield),f,t,rounds,killBonus)
                    end
                    local own=hitsFor(gives.hits,f,caster,aim)
                    if f~=caster then more=M.offense(gives.buff,f,frame,fights,nil,nil,own,tables)
                    elseif wielded then more=M.offense(gives.buff,f,frame,fights,wielded,gives.own,own,tables) end
                    gain=gain+more
                    if gain>0 then worth=worth+gain;hits[#hits+1]=f.id;boost=boost+more end
                end
            end
            if open>0 then
                local listed=false
                for _,id in ipairs(hits) do if id==caster.id then listed=true end end
                if not listed then table.insert(hits,1,caster.id) end
            end
            -- Caution weighs what it gives the side; a profile without any (labs) still sees it.
            local weak=(row.item or away) and 0 or weakens(input,row,spell,aim,ac)
            local total=worth*caution+weak+open
            if worth+weak+open>0 and (not best or total>best.total or (total==best.total and worth>best.worth)) then
                best={aim=aim,total=total,worth=worth,hits=hits,open=open,boost=boost}
            end
        end
        if not best then return false,unknown and 'unknown-guard' or 'no-worth' end
        -- Casting time: harm while casting can interrupt a cast (not a drink); long casts also cost.
        local through=row.item and 1 or M.through(input,ct,cast)
        local level=row.item and M.itemLevel or slots(input)*(number(row.level) and row.level or
            number(spell.level) and spell.level or 1)
        local cost=(number(mind.economy) and mind.economy or 1)*M.costPerLevel*level+
            (number(mind.castCost) and mind.castCost or 0)*cast
        local worth=best.total*through
        local option={resref=row.resref,kind='defence',worth=worth,cost=cost,score=worth-cost,
            hits=best.hits,slack=0,speed=number(spell.speed) and spell.speed or 0,release=spell.release or nil,
            use=row.item or nil,hides=best.open>0 or nil,opening=best.open>0 and best.open or nil,
            rest=gives.buff and rest or nil,boosts=best.boost>0 or nil}
        local aim=best.aim
        if aim.self then option.self=true;option.mode='self'
        elseif aim.friend then option.target=aim.friend.id;option.mode='ally'
        else option.point={x=math.floor(aim.point.x+0.5),y=math.floor(aim.point.y+0.5)};option.mode='point' end
        return option
    end
    for _,row in ipairs(type(input.spells)=='table' and input.spells or {}) do
        if type(row)=='table' and number(row.ready) and row.ready>0 and row.usable then
            local option,why=consider(row,row.spell)
            if option then out[#out+1]=option elseif why then reject(why) end
        end
    end
    -- Items the caster carries: the first ability of each that defends, while uses are left.
    for _,it in ipairs(type(input.items)=='table' and input.items or {}) do
        if type(it)=='table' and type(it.resref)=='string' then
            for _,a in ipairs(type(it.abilities)=='table' and it.abilities or {}) do
                local effect=type(a)=='table' and a.effect
                if type(effect)=='table' and effect.target~='point' and (not number(a.uses) or a.uses>0) and M.defence(effect) then
                    local option,why=consider({resref=it.resref,item=true},effect)
                    if option then out[#out+1]=option elseif why then reject(why) end
                    break
                end
            end
        end
    end
    return out
end
return M
end
factories["combat-intent.care"]=function(require)
-- The engine's own healing and curing for one caster (step 3, D3a and D3b; Christopher,
-- 2026-10-20: "Mach alles"). SCS's priests are the blueprint ([src] priest/ssl/generalblocks/
-- renew.ssl): they heal themselves and allies who are hurt, and cure what keeps an ally out of the
-- fight, before they attack; they heal and cure only allies above a level that rises with their
-- own (priest_shared.tph, minimum_healing_level). SCS's mages and priests drink healing potions.
--
-- Inputs are plain values, as for combat-intent/defence.lua: the caster's frame, whose friends
-- (the caster and its allies) carry their level and guard (what protects them, and the conditions
-- on them with the seconds left: adapters/eeex/sense.lua), the classified ready spells and the
-- carried items, the profile and the director's plan. Nothing here touches the engine or raises
-- on odd data.
--
-- Worth is on the attack's scale (shares of a creature), as for protections: what a friend is
-- worth at the horizon's end with the cast less what it is worth without, counting the share of
-- its hit points it has left then, the kill bonus as likely as it lives, and the rounds it is in
-- the fight (alive and not disabled), each worth a round of disable (defence.disableRound). A heal
-- on a friend no one threatens is worth the hit points it restores, as damage on an enemy is; on
-- a friend about to fall also the rounds it keeps it standing and the kill bonus. A friend that
-- falls before the cast lands gains nothing. A cure is worth what the condition would still keep
-- the friend out of, as the same disable on an enemy is worth (combat-intent/choice.lua), and the
-- hit points poison would still take.
--
-- A walk into range to an ally comes first and lowers the worth as for an attack spell
-- (weapons.paced, at the caster's speed: one walk rule for heals and attacks), and the friend must
-- stand the walk and the casting.
local targeting=require('combat-intent.targeting')
local threat=require('combat-intent.threat')
local defence=require('combat-intent.defence')
local weapons=require('combat-intent.weapons')
local ids=require('combat-intent.ids')
local M={}
M.ROUND=6
-- What freeing a friend of each condition is worth for the full time (fullSeconds), as the same
-- disable on an enemy is worth (choice.DISABLE); blindness, deafness and disease hinder without
-- taking the friend out. Conditions that matter only for casters count a fifth on others.
M.CONDITION={sleep=0.8,hold=1,stun=1,panic=0.7,confusion=0.8,berserk=0.4,feeblemind=1,silence=0.7,
    pause=0.8,blind=0.3,deaf=0.2,disease=0.1}
M.CASTERS_ONLY={feeblemind=true,silence=true,deaf=true}
M.fullSeconds=18
-- Seconds a condition counts for when the friend's effects could not be read.
M.unknownSeconds=12
-- The STATE.IDS bit each condition shows in (holds set the HELD stat); a condition whose effect
-- is on a friend but whose state does not show any more is over. Deafness and the casting pause
-- show in no state.
M.STATE={sleep=0x1,berserk=0x2,panic=0x4,stun=0x8,silence=0x1000,poison=0x4000,blind=0x40000,
    disease=0x80000,feeblemind=0x100000,confusion=0x80000000}
-- How far beyond a spell's range the caster walks to an ally it heals or cures (a touch spell
-- reaches one range unit): a round's walk, at about 100 world units a second.
M.walk=600
-- A speed point of casting time is 10 game ticks (as for defences).
M.speedSeconds=10/15
-- Worth of one spell level, times the profile's economy; a potion costs as a first-level spell.
M.costPerLevel=0.03
M.itemLevel=1

local function number(v) return type(v)=='number' and v==v and v>-math.huge and v<math.huge end
-- The share of a spell slot's cost that counts now (combat-intent/choice.lua, M.slotShare).
local function slots(input) return number(input.slots) and input.slots or 1 end
local function clamp(v,a,b) if v<a then return a elseif v>b then return b end return v end
local function list(t) return type(t)=='table' and t or {} end

-- The level an ally must exceed for SCS's priests of this level to heal or cure it
-- (priest_shared.tph, minimum_healing_level; renew.ssl: CheckStatGT on the ally's level).
function M.minimumLevel(level)
    if not number(level) or level<=3 then return 1 end
    if level<=5 then return 2 end
    if level<=7 then return 3 end
    if level<=8 then return 4 end
    if level<=14 then return level-5 end
    if level<=17 then return level-6 end
    if level<=20 then return level-7 end
    return level-8
end

-- Hit points a heal role restores on friend f now: its amount, or its share of f's maximum, up
-- to what f is missing. A heal that sets hit points or rests is not counted.
function M.healed(role,f)
    if type(role)~='table' or not number(f.hp) or not number(f.maxHp) or f.maxHp<=0 then return 0 end
    local missing=math.max(0,f.maxHp-f.hp)
    local amount=0
    if number(role.amount) then amount=amount+role.amount end
    if number(role.percent) then amount=amount+f.maxHp*role.percent/100 end
    return math.min(amount,missing)
end

local NONE={weapon={hp=0,hits=0,attacks=0,magicalAttacks=0},spell={hp=0,personal=0,area=0,disable=0,casters=0,level=0}}
-- What friend f is worth at the end of r rounds under threat t with shield s, if it had hp hit
-- points now: the share of its hit points left then, the kill bonus as likely as it lives (for
-- sure while its minimum holds), and the rounds it is in the fight (alive and not disabled by
-- enemy spells), each worth a round of disable. Harm runs as defence.course has it.
function M.standing(f,t,s,r,killBonus,hp)
    local maxHp=number(f.maxHp) and f.maxHp>0 and f.maxHp or 1
    if hp<=0 then return 0 end
    local g={}
    for k,v in pairs(f) do g[k]=v end
    g.hp=hp
    local harm,death,b=defence.course(s,g,t or NONE,r)
    local dies=targeting.minimum(f)>0 and 0 or clamp((harm-0.5*hp)/(0.5*hp),0,1)
    local alive=math.min(death,r)
    local disabled=(t or NONE).spell.disable*(1-b.disable)*alive
    return math.max(0,hp-harm)/maxHp+killBonus*(1-dies)+defence.disableRound*(alive-disabled)
end

-- Whether friend f has condition label now, and its seconds left: the effect on f (its guard's
-- conditions) while its state still shows it; a hold shows in the HELD stat. A friend whose
-- effects could not be read counts by its state alone, for unknownSeconds.
function M.condition(f,label)
    local shown
    if label=='hold' then shown=number(f.held) and f.held>0
    elseif M.STATE[label] then shown=targeting.has(f.state,M.STATE[label]) end
    local guard=type(f.guard)=='table' and f.guard or nil
    local left=guard and type(guard.conditions)=='table' and guard.conditions[label]
    if not guard then
        if shown then return true,M.unknownSeconds end
        return false,0
    end
    -- (A condition without an end lasts math.huge seconds.)
    if not (type(left)=='number' and left>0) then return false,0 end
    if shown==false then return false,0 end
    return true,left
end

-- The worth of a cure role on friend f: each condition it takes away that f has, as that
-- disable would be worth on an enemy for the time it has left, and the share of f's hit points
-- poison would still take.
function M.cured(role,f)
    if type(role)~='table' or type(role.kinds)~='table' then return 0,{} end
    local worth,freed=0,{}
    local health=targeting.health(f)
    for label in pairs(role.kinds) do
        local has,left=M.condition(f,label)
        if has then
            local factor=M.CONDITION[label] or 0
            if M.CASTERS_ONLY[label] and not ids.caster(f) then factor=factor*0.2 end
            if factor>0 then
                worth=worth+factor*clamp(left/M.fullSeconds,0,1)*(0.5+0.5*health)
                freed[#freed+1]=label
            end
            if label=='poison' then
                local guard=type(f.guard)=='table' and f.guard or {}
                local hp=number(guard.poison) and guard.poison or 0
                local maxHp=number(f.maxHp) and f.maxHp>0 and f.maxHp or nil
                if hp>0 and maxHp then
                    worth=worth+math.min(hp,math.max(0,f.hp or 0))/maxHp
                    freed[#freed+1]=label
                end
            end
        end
    end
    return worth,freed
end

-- The heal and cure roles of a spell or item ability that reach friends, or nil and why it is no
-- care: an attack, a spell that also harms or removes, one that reaches the party (for the
-- engine's creatures that is the enemy), or one without such roles.
function M.care(spell)
    if type(spell)~='table' or type(spell.roles)~='table' then return nil,'unclassified' end
    local h,c=spell.roles.heal,spell.roles.cure
    local function reaches(role)
        return type(role)=='table' and type(role.who)=='table' and (role.who.self or role.who.target or role.who.area)
    end
    if not reaches(h) and not reaches(c) then return nil,'no-care' end
    if spell.partial then return nil,'partial' end
    if spell.offensive or spell.selfHarm then return nil,'offensive' end
    for _,r in ipairs({h,c}) do
        if type(r)=='table' and type(r.who)=='table' and (r.who.party or r.who.everyone or r.who.nonparty) then
            return nil,'party'
        end
    end
    return {heal=reaches(h) and h or nil,cure=reaches(c) and c or nil}
end

-- Where a care spell can be cast: on the caster, and at each ally it sees (targeting.seen) within
-- its range and a round's walk beyond it for a spell cast at a creature; at the caster's spot or
-- such an ally's for an area at a point; around the caster for its own area. walk: the seconds the
-- caster walks into range first (weapons.approach); none beyond range for a caster that cannot walk.
local function aims(input,spell)
    local frame=input.frame
    local caster=frame.self
    local out={}
    local range=(number(spell.range) and spell.range or 0)*targeting.rangeUnit
    local function walk(f)
        if targeting.distance(caster,f)>range+M.walk then return nil end
        return weapons.approach(caster,f,range)
    end
    if spell.target=='self' then
        out[1]={self=true,friend=caster,point=spell.area and {x=caster.x,y=caster.y} or nil,walk=0}
    elseif spell.target=='point' and spell.area then
        out[1]={point={x=caster.x,y=caster.y},walk=0}
        for _,f in ipairs(threat.friends(frame)) do
            local w=f~=caster and targeting.seen(caster,f) and walk(f)
            if w then out[#out+1]={point={x=f.x,y=f.y},walk=w} end
        end
    elseif spell.target=='creature' then
        out[1]={self=true,friend=caster,walk=0}
        for _,f in ipairs(threat.friends(frame)) do
            local w=f~=caster and targeting.seen(caster,f) and walk(f)
            if w then out[#out+1]={friend=f,walk=w} end
        end
    end
    return out
end
-- Who a role reaches, aimed as the cast is: the caster for its own part, the creature aimed at,
-- the friends in its area (the enemies too, when the area spares no one).
local function receivers(input,spell,role,aim)
    local frame=input.frame
    local friends,foes,seen={},{},{}
    local function add(f) if f and not seen[f] then seen[f]=true;friends[#friends+1]=f end end
    if role.who.self then add(frame.self) end
    if role.who.target and aim.friend then add(aim.friend) end
    if role.who.area then
        local filters=type(role.filters)=='table' and role.filters or {all=true}
        local area=spell.area
        local center=aim.point or (aim.friend and {x=aim.friend.x,y=aim.friend.y})
        if area and number(area.radius) and center and (filters.allies or filters.all) then
            for _,f in ipairs(threat.friends(frame)) do
                if targeting.distance(center,f)<=area.radius then add(f) end
            end
            if filters.all then
                for _,e in ipairs(list(frame.enemies)) do
                    if targeting.alive(e) and targeting.distance(center,e)<=area.radius then foes[#foes+1]=e end
                end
            end
        end
    end
    return friends,foes
end

-- Every heal and cure option the caster has: {resref, kind='heal' or 'cure', mode, worth, cost,
-- score, hits (the friends it helps), slack=0, speed, and self, target or point as it is aimed;
-- use=true for an item it drinks}. rejected (optional) counts why ready care spells gave none.
-- An ally at or below SCS's healing level for the caster's level, or one another member of the
-- group is already healing or curing (the director's plan, with coordination), is left out.
function M.options(input,rejected)
    local out={}
    local function reject(why) if rejected then rejected['care-'..why]=(rejected['care-'..why] or 0)+1 end end
    local mind=input.mind
    local frame=input.frame
    if type(frame)~='table' or type(frame.self)~='table' or type(mind)~='table' then return out end
    local caster=frame.self
    local pictures=threat.picture(frame)
    local horizon=number(mind.horizon) and mind.horizon or 18
    local rounds=horizon/M.ROUND
    local killBonus=number(mind.killBonus) and mind.killBonus or 0
    local minimum=M.minimumLevel(caster.level)
    local plan=type(input.plan)=='table' and input.plan or {}
    local reserved=type(plan.reserved)=='table' and plan.reserved or {}
    local coordinated=(number(mind.coordination) and mind.coordination or 0)>=0.5
    local shields={}
    local function shieldOf(f) shields[f.id]=shields[f.id] or defence.held(f);return shields[f.id] end
    -- The worth on friend f of the heal and the cure of spell that reach it, once a cast that lands
    -- the given seconds from now (a walk and the casting) lands. A spell f's protections keep out
    -- does nothing for it (lab batch H: SCS's Minor Globe of Invulnerability kept a Remove Paralysis
    -- off a held mage); the caster's own protections let its own help through (targeting.protected).
    local function on(f,heal,cure,cast,spell)
        if f~=caster then
            if number(f.level) and f.level<=minimum then return 0,'level' end
            local owner=reserved[f.id]
            if coordinated and owner~=nil and owner~=caster.id then return 0,'reserved' end
        end
        if type(f.protections)=='table' and targeting.protected(f,spell,f==caster) then return 0,'protected' end
        local t=pictures[f.id]
        local s=shieldOf(f)
        local worth=0
        if heal then
            local healed=M.healed(heal,f)
            if healed>0 then
                -- Harm while the cast runs: a friend that falls meanwhile gains nothing.
                local lead=cast/M.ROUND
                local hp=f.hp
                if t and lead>0 then
                    local harm,death=defence.course(s,f,t,lead)
                    if death<=lead then return 0,'falls' end
                    hp=math.max(1,f.hp-harm)
                end
                worth=worth+M.standing(f,t,s,rounds,killBonus,hp+healed)-M.standing(f,t,s,rounds,killBonus,hp)
            end
        end
        if cure then worth=worth+(M.cured(cure,f)) end
        return worth,worth<=0 and 'no-worth' or nil
    end
    local function consider(resref,spell,gives,level,item)
        local cast=(number(spell.speed) and spell.speed or 0)*M.speedSeconds
        local best,why
        local candidates=item and {{self=true,friend=caster,walk=0}} or aims(input,spell)
        for _,aim in ipairs(candidates) do
            -- Who each role reaches; healing an enemy in an area that spares no one counts
            -- against the cast.
            local reach,order,worth,hits={},{},0,{}
            for name,role in pairs(gives) do
                local friends,foes=receivers(input,spell,role,aim)
                for _,f in ipairs(friends) do
                    if not reach[f] then reach[f]={};order[#order+1]=f end
                    reach[f][name]=role
                end
                if name=='heal' then
                    for _,e in ipairs(foes) do
                        local maxHp=number(e.maxHp) and e.maxHp>0 and e.maxHp or nil
                        if maxHp then worth=worth-M.healed(role,e)/maxHp end
                    end
                end
            end
            table.sort(order,function(a,b) return (a.id or 0)<(b.id or 0) end)
            for _,f in ipairs(order) do
                local w,no=on(f,reach[f].heal,reach[f].cure,cast+aim.walk,spell)
                -- The most telling reason a friend gains nothing: anything but plain no worth.
                if w>0 then worth=worth+w;hits[#hits+1]=f.id
                elseif no and (why==nil or why=='no-worth') then why=no end
            end
            -- A walk into range comes first and lowers the worth (weapons.paced).
            worth=worth*weapons.paced(aim.walk)
            if worth>0 and (not best or worth>best.worth) then best={aim=aim,worth=worth,hits=hits} end
        end
        if not best then reject(why or 'no-worth');return end
        -- Casting time: harm while casting can interrupt a spell (not an item); long casts cost.
        local through=item and 1 or defence.through(input,pictures[caster.id],cast)
        local cost=(number(mind.economy) and mind.economy or 1)*M.costPerLevel*(item and M.itemLevel or slots(input)*level)+
            (number(mind.castCost) and mind.castCost or 0)*cast
        local worth=best.worth*through
        local option={resref=resref,kind=gives.heal and 'heal' or 'cure',worth=worth,cost=cost,score=worth-cost,
            hits=best.hits,slack=0,speed=number(spell.speed) and spell.speed or 0,use=item or nil,
            walk=best.aim.walk>0 and best.aim.walk or nil}
        local aim=best.aim
        if aim.self then option.self=true;option.mode='self'
        elseif aim.friend then option.target=aim.friend.id;option.mode='ally'
        else option.point={x=math.floor(aim.point.x+0.5),y=math.floor(aim.point.y+0.5)};option.mode='point' end
        out[#out+1]=option
    end
    for _,row in ipairs(list(input.spells)) do
        if type(row)=='table' and number(row.ready) and row.ready>0 and row.usable then
            local gives,why=M.care(row.spell)
            if gives then
                local level=number(row.level) and row.level or number(row.spell.level) and row.spell.level or 1
                consider(row.resref,row.spell,gives,level,false)
            elseif why~='no-care' and why~='unclassified' then reject(why) end
        end
    end
    -- Items the caster carries: their abilities on itself, while uses are left.
    for _,it in ipairs(list(input.items)) do
        if type(it)=='table' and type(it.resref)=='string' then
            for _,a in ipairs(list(it.abilities)) do
                local effect=type(a)=='table' and a.effect
                local gives=effect and M.care(effect)
                if gives and (not number(a.uses) or a.uses>0) and effect.target~='point' then
                    consider(it.resref,effect,gives,M.itemLevel,true)
                    break
                end
            end
        end
    end
    return out
end
return M
end
factories["combat-intent.summons"]=function(require)
-- The engine's own summons for one caster (step 3, D3c; Christopher, 2026-10-20: "Mach alles").
-- SCS is the blueprint ([src] its mage and priest summoning blocks): its casters cast most summons
-- at an enemy they target (elementals, monster summonings, the dead, Devas), a few on themselves
-- (Gate, Summon Fiend, Death Knight, Mordenkainen's Sword, the genies), and those that eat magic
-- (Nishruu, Hakeashar) at an enemy caster. Apart from one Deva at a time it counts no summons of
-- its own; the engine stops at a cap of summoned allies in view (the profile's summonCap), as the
-- game limits summoned creatures.
--
-- Inputs are plain values: the frame (enemies with attack data from adapters/eeex/sense.lua,
-- allies with IDS values), the classified ready spells, the profile, the director's plan, and
-- input.creatures: each creature the ready spells name, as M.profile reads its CRE record and
-- weapon (the adapter reads them). Nothing here touches the engine or raises on odd data.
--
-- Worth is on the attack's scale: each summoned creature's fight, the share of an enemy its hits
-- take (as a weapon attack is worth) and the share of a friend its body spares by drawing its part
-- of the enemies' blows, up to its own hit points. It fights over the rest of the fight after the
-- cast, as both sides' strength makes it (combat-intent/threat.lua, M.rest; at most the profile's
-- fightCap), no longer than the summons lasts and only while it lives; so an early summons counts
-- much and a late one little (Christopher, 2026-10-22, agreed). While the caster's side awaits foes
-- out of play (input.calm, combat-intent/choice.lua's readiness; Christopher, 2026-10-29: "Was für
-- eine geile Idee") a summons waits where they went, as the readied frame places them, and fights
-- from when the first is likely back on. Only fighters on the caster's side count:
-- - a creature no one can see or select (its own effects remove its avatar or its selection
--   circle: SCS's markers for its storms and clouds, a kit's helper) or without a weapon is no
--   fighter;
-- - a summons that takes its side from its own file joins the caster only when that side is the
--   caster's (Wish's genie is neutral); one aligned against the caster is hostile.
-- Summons from monster tables (opcodes 127 and 331) name no creature; they count as creatures of
-- twice the spell's level. Cost: the spell's level and its casting time; harm while casting can
-- break it. Not yet: images of the caster (Project Image, Simulacrum), changes of shape, and
-- summons cast at another creature, whose side follows that creature.
local targeting=require('combat-intent.targeting')
local threat=require('combat-intent.threat')
local defence=require('combat-intent.defence')
local weapons=require('combat-intent.weapons')
local arsenal=require('combat-intent.arsenal')
local M={}
M.ROUND=6
-- Opcodes of a creature's own effects that make it no fighter: avatar removal, selection circle
-- removal.
M.HIDDEN={[271]=true,[287]=true}
-- GENDER.IDS SUMMONED: the creatures the cap counts (summoned demons and illusions do not).
M.SUMMONED=6
-- EA.IDS: the good side ends at GOODCUTOFF, the evil side starts at EVILCUTOFF.
M.GOOD_CUTOFF=30
M.EVIL_CUTOFF=200
-- A speed point of casting time is 10 game ticks (as for defences); a spell level costs this,
-- times economy.
M.speedSeconds=10/15
M.costPerLevel=0.03
-- Mean enemy armour class and hit points when no enemy shows them.
M.enemyAc=5
M.enemyHp=60

local function number(v) return type(v)=='number' and v==v and v>-math.huge and v<math.huge end
-- The share of a spell slot's cost that counts now (combat-intent/choice.lua, M.slotShare).
local function slots(input) return number(input.slots) and input.slots or 1 end
local function list(t) return type(t)=='table' and t or {} end
local function average(dice,sides)
    if number(dice) and number(sides) and dice>0 and sides>0 then return dice*(sides+1)/2 end
    return 0
end
local function magic(record)
    return (number(record.enchantment) and record.enchantment>0) or
        (number(record.flags) and math.floor(record.flags/64)%2==1) or false
end

-- The side of an EA value, as adapters/eeex/sense.lua groups them: 'evil', 'good' or nil.
function M.side(ea)
    if not number(ea) then return nil end
    if ea>=M.EVIL_CUTOFF then return 'evil' end
    if ea>=2 and ea<=M.GOOD_CUTOFF then return 'good' end
end

-- STRMOD.2DA's bonuses to hit and to damage for a strength (the game's shipped table; exceptional
-- strength 18/01 to 18/00 by its percentile).
M.strength=arsenal.shippedStrength

-- A creature as a fighter, from its CRE record (adapters/eeex/resources.lua), the record of the
-- weapon in its first weapon slot and, for a launcher, of the ammunition in its first filled
-- quiver slot (nil for none): hit points, armour class, THAC0 with its bonuses, attacks a round,
-- the average damage of a hit with what the weapon's own effects add, whether the weapon is
-- magical, its EA and gender, and whether it fights at all. Strength counts for melee only.
function M.profile(cre,weapon,ammo)
    if type(cre)~='table' or not number(cre.maxHp) then return nil end
    local ability=type(weapon)=='table' and type(weapon.abilities)=='table' and weapon.abilities[1] or nil
    if type(ability)~='table' then ability=nil end
    local fighter=cre.maxHp>1 and ability~=nil
    for _,op in ipairs(list(cre.opcodes)) do if M.HIDDEN[op] then fighter=false end end
    local hit,damage,magical,ranged=0,0,false,false
    if ability then
        damage=average(ability.dice,ability.sides)+(number(ability.damageBonus) and ability.damageBonus or 0)+
            weapons.onHit(ability)
        hit=number(ability.thac0) and ability.thac0 or 0
        magical=magic(weapon)
        ranged=ability.attackType==2 or ability.attackType==4
        if ability.attackType==4 then
            local shot=type(ammo)=='table' and type(ammo.abilities)=='table' and ammo.abilities[1] or nil
            if type(shot)=='table' then
                damage=damage+average(shot.dice,shot.sides)+(number(shot.damageBonus) and shot.damageBonus or 0)+
                    weapons.onHit(shot)
                hit=hit+(number(shot.thac0) and shot.thac0 or 0)
                magical=magical or magic(ammo)
            else fighter=false end
        end
    end
    if not ranged then
        local strHit,strDamage=M.strength(cre.strength,cre.strengthExtra)
        hit=hit+strHit
        if ability then damage=damage+strDamage end
    end
    return {resref=cre.resref,maxHp=cre.maxHp,ac=number(cre.ac) and cre.ac or 10,
        thac0=(number(cre.thac0) and cre.thac0 or 20)-hit,apr=math.max(defence.attacks(cre.apr),0),
        damage=math.max(damage,0),magical=magical,ranged=ranged,fighter=fighter,level=cre.level,
        gender=cre.gender,ea=cre.ea}
end
