local M={}
M.ticksPerSecond=15
-- CLASS.IDS: THIEF, FIGHTER_THIEF, FIGHTER_MAGE_THIEF, MAGE_THIEF, CLERIC_THIEF.
M.THIEVES={[4]=true,[9]=true,[10]=true,[13]=true,[15]=true}
