        local item=equipment.m_items:get(slot)
        if item~=nil and (type(toPtr)~='function' or toPtr(item)~=0) then
            local resref=text(item.cResRef)
            if resref and resref~='' then out[resref]=true end
        end
    end
    return out
end
return M
end
