            if not prepHeld[key] then
                if prepHeldCount>=M.cacheLimit then prepHeld,prepHeldCount={},0 end
                prepHeld[key]=true;prepHeldCount=prepHeldCount+1
                counts.prepHolds=counts.prepHolds+1
